using System;using System.Collections.Generic;using System.Data;using System.Data.SqlClient;using System.Diagnostics;using System.Globalization;using System.IO;using System.Text.RegularExpressions;using System.Web;using System.Web.Script.Serialization;
namespace WebVault { public sealed class TrashHandler:IHttpHandler {
public sealed class Input { public string action{get;set;} public string path{get;set;} public string expectedStamp{get;set;} }
public bool IsReusable {get{return false;}}
static string Resolve(string root,string relative){if(String.IsNullOrEmpty(relative)||relative.Length>180||relative.IndexOf('\\')>=0)throw new ApiFailure(400,"invalid_path");string[] parts=relative.Split('/');if(parts.Length>16)throw new ApiFailure(400,"invalid_path");string path=root;foreach(string p in parts){if(String.IsNullOrEmpty(p)||p.Length>100||p!=p.Trim()||p.StartsWith(".")||p.EndsWith(".")||p.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(p.Split('.')[0],@"\A(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]|CONIN\$|CONOUT\$)\z",RegexOptions.IgnoreCase))throw new ApiFailure(400,"invalid_path");foreach(char ch in p)if(Char.IsControl(ch))throw new ApiFailure(400,"invalid_path");path=Path.Combine(path,p);if((File.Exists(path)||Directory.Exists(path))&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new ApiFailure(409,"reparse_point_not_allowed");}path=Path.GetFullPath(path);if(path.Length>240||!path.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))throw new ApiFailure(400,"invalid_path");return path;}
static void Scan(string path,string rel,List<string> rows,ref long bytes,Stopwatch watch,string target){if(rows.Count>=2000||watch.ElapsedMilliseconds>10000||path.Length>240||target.Length>240||rel.Split('/').Length>16)throw new ApiFailure(409,"operation_tree_limit");FileAttributes a=File.GetAttributes(path);if((a&FileAttributes.ReparsePoint)!=0)throw new ApiFailure(409,"reparse_point_not_allowed");bool dir=(a&FileAttributes.Directory)!=0;long length=dir?0:new FileInfo(path).Length;bytes+=length;if(bytes>52428800)throw new ApiFailure(409,"operation_tree_limit");rows.Add((dir?"D":"F")+"|"+rel+"|"+length.ToString(CultureInfo.InvariantCulture)+"|"+File.GetLastWriteTimeUtc(path).Ticks.ToString(CultureInfo.InvariantCulture));if(dir)foreach(string child in Directory.EnumerateFileSystemEntries(path)){string name=Path.GetFileName(child);Scan(child,rel.Length==0?name:rel+"/"+name,rows,ref bytes,watch,Path.Combine(target,name));}}
public void ProcessRequest(HttpContext c){bool moved=false;string id=null;try{WebApi.Prepare(c);WebApi.Post(c);ApiUser u=WebApi.RequireUser(c,true);if(u.IsAdmin)throw new ApiFailure(403,"personal_account_required");if(c.Request.Headers["X-WebVault-User"]!=u.UserId.ToString(CultureInfo.InvariantCulture))throw new ApiFailure(409,"session_changed");Input i=WebApi.Read<Input>(c);if(i.action!="trash")throw new ApiFailure(400,"invalid_action");using(SqlConnection db=WebApi.Open())using(SqlTransaction tx=db.BeginTransaction()){using(SqlCommand q=new SqlCommand(@"SELECT UserId FROM auth.Users WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u AND IsActive=1 AND IsAdmin=0 AND DeletedUtc IS NULL AND MustChangePassword=0 AND EXISTS(SELECT 1 FROM auth.UserSessions WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u AND SessionId=@s AND RevokedUtc IS NULL AND ExpiresUtc>SYSUTCDATETIME() AND AbsoluteExpiresUtc>SYSUTCDATETIME())",db,tx)){q.Parameters.Add("@u",SqlDbType.Int).Value=u.UserId;q.Parameters.Add("@s",SqlDbType.BigInt).Value=u.SessionId;if(q.ExecuteScalar()==null)throw new ApiFailure(401,"unauthenticated");}Guid vault;using(SqlCommand q=new SqlCommand("SELECT VaultId FROM storage.UserVaults WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u",db,tx)){q.Parameters.Add("@u",SqlDbType.Int).Value=u.UserId;object v=q.ExecuteScalar();if(v==null)throw new ApiFailure(409,"vault_not_initialized");vault=(Guid)v;}string root=Path.Combine(VaultHandler.DataRoot(c),"vaults",vault.ToString("N"));VaultHandler.PlainDirectory(root);string source=Resolve(root,i.path);if(!File.Exists(source)&&!Directory.Exists(source))throw new ApiFailure(404,"entry_not_found");bool dir=Directory.Exists(source);string trash=Path.Combine(root,".wv-trash");if(File.Exists(trash))throw new ApiFailure(409,"trash_invalid");if(Directory.Exists(trash))VaultHandler.PlainDirectory(trash);id=Guid.NewGuid().ToString("N");string target=Path.Combine(trash,id);List<string> rows=new List<string>();long bytes=0;Scan(source,"",rows,ref bytes,Stopwatch.StartNew(),target);rows.Sort(delegate(string a,string b){string ar=a.Split('|')[1],br=b.Split('|')[1];return StringComparer.Ordinal.Compare(ar,br);});string stamp=Convert.ToBase64String(AuthCrypto.Hash(String.Join("\n",rows.ToArray())));if(!String.Equals(stamp,i.expectedStamp,StringComparison.Ordinal))throw new ApiFailure(409,"source_changed_refresh");if(!Directory.Exists(trash))Directory.CreateDirectory(trash);VaultHandler.PlainDirectory(trash);string meta=Path.Combine(trash,id+".json");byte[] data=new System.Text.UTF8Encoding(false).GetBytes(new JavaScriptSerializer().Serialize(new{operationId=id,source=i.path,kind=dir?"folder":"file",createdUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture),payload=id}));using(FileStream f=new FileStream(meta,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(data,0,data.Length);f.Flush(true);}if(dir)Directory.Move(source,target);else File.Move(source,target);moved=true;tx.Commit();WebApi.Reply(c,200,new{ok=true,operationId=id,path=i.path});}}catch(Exception e){if(moved){Trace.TraceError("Trash acknowledgement uncertain {0}: {1}",id,e.GetType().Name);WebApi.Reply(c,503,new{ok=false,error="trash_result_uncertain_refresh_tree",errorId=id});}else if(e is FileNotFoundException||e is DirectoryNotFoundException)WebApi.Error(c,new ApiFailure(404,"entry_not_found"));else WebApi.Error(c,e);}}
} }
